class Base {
public:
    virtual void foo();
    virtual ~Base();
};

class Derived : public Base {
public:
    void foo() override;
    ~Derived() override;
};

// Implementation notes:
// - Objects of these classes contain a pointer to a vtable at a fixed offset.
// - The vtable is an array of function pointers generated by the compiler.
// - During construction, the compiler sets up the vtable pointer according to the current class.
// - Virtual calls are resolved via the vtable pointer at runtime.
// - Destructors are called in reverse order of inheritance, with vtable adjustments.
// - Inheritance causes the derived object to include the base subobject layout.
// - Compiler optimizations may include vtable caching, inlining, and layout adjustments.
